            seen.add((r, c))
            comp = []
            while stack:
                x, y = stack.pop()
                comp.append((x, y))
                for dx, dy in ((1,0),(-1,0),(0,1),(0,-1)):
                    nx, ny = x+dx, y+dy
                    if 0 <= nx < h and 0 <= ny < w and grid[nx][ny] == 8 and (nx,ny) not in seen:
                        seen.add((nx,ny)); stack.append((nx,ny))
            if min(c for _, c in comp) == 0 and len(comp) >= 5 and min(r for r,_ in comp) > h//3:
                for x, y in comp:
                    out[x][y] = 5
    return out
