    from collections import Counter
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    # Detect the long vertical marker and its horizontal hook.
    marks = []
    for c in range(w):
        for color in range(10):
            if color == bg:
                continue
            r = 0
            while r < h:
                if grid[r][c] != color:
                    r += 1
                    continue
                a = r
                while r < h and grid[r][c] == color:
                    r += 1
                b = r - 1
                if b - a + 1 < 6:
                    continue
                for end in (a, b):
                    left = 0
                    x = c - 1
                    while x >= 0 and grid[end][x] == color:
                        left += 1
                        x -= 1
                    right = 0
                    x = c + 1
                    while x < w and grid[end][x] == color:
                        right += 1
                        x += 1
                    if max(left, right) >= 2:
                        marks.append((b-a+1, color, c, end, left, right))
    if not marks:
        return [row[:] for row in grid]
    _, marker, mc, elbow, left, right = max(marks)
    side = 0 if left > right else w - 1
    # The hook selects the matching edge; of its objects, recolor the largest
    # one furthest from the hook's row (the demo has two equal edge stripes).
    seen = set()
    candidates = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color in (bg, marker) or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            comp = []
            while stack:
                x, y = stack.pop()
                comp.append((x, y))
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nx, ny = x + dx, y + dy
                    if 0 <= nx < h and 0 <= ny < w and grid[nx][ny] == color and (nx, ny) not in seen:
                        seen.add((nx, ny))
                        stack.append((nx, ny))
            if any(y == side for x, y in comp):
                candidates.append(comp)
    if not candidates:
        return [row[:] for row in grid]
    comp = max(candidates, key=lambda cells: (len(cells), abs(sum(x for x, y in cells) / len(cells) - elbow)))
    out = [row[:] for row in grid]
    for r, c in comp:
        out[r][c] = marker
    return out
