 "content": "def transform(grid):
    from collections import Counter
    h = len(grid)
    w = max(map(len, grid))
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]

    # Find the long vertical marker with a horizontal hook at an endpoint.
    hooks = []
    for c in range(w):
        for color in range(10):
            if color == bg:
                continue
            r = 0
            while r < h:
                if c >= len(grid[r]) or grid[r][c] != color:
                    r += 1
                    continue
                top = r
                while r < h and c < len(grid[r]) and grid[r][c] == color:
                    r += 1
                bottom = r - 1
                if bottom - top + 1 < 6:
                    continue
                for endpoint in (top, bottom):
                    left = 0
                    x = c - 1
                    while x >= 0 and grid[endpoint][x] == color:
                        left += 1
                        x -= 1
                    right = 0
                    x = c + 1
                    while x < len(grid[endpoint]) and grid[endpoint][x] == color:
                        right += 1
                        x += 1
                    if max(left, right) >= 2:
                        hooks.append((bottom - top + 1, color, endpoint,
                                      0 if left > right else 1))
    out = [row[:] for row in grid]
    if not hooks:
        return out
    _, marker, elbow, direction = max(hooks)
    edge_col = 0 if direction == 0 else w - 1

    # Recolor the edge-touching object below the elbow, in the hook's direction.
    seen = set()
    targets = []
    for r in range(h):
        for c in range(len(grid[r])):
            color = grid[r][c]
            if color in (bg, marker) or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            comp = []
            while stack:
                x, y = stack.pop()
                comp.append((x, y))
                for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nr, nc = x + dr, y + dc
                    if (0 <= nr < h and 0 <= nc < len(grid[nr]) and
                            grid[nr][nc] == color and (nr, nc) not in seen):
                        seen.add((nr, nc))
                        stack.append((nr, nc))
            if any(y == edge_col for x, y in comp) and max(x for x, y in comp) > elbow:
                targets.append(comp)
    if targets:
        target = max(targets, key=lambda comp: (len(comp), min(x for x, y in comp)))
        for r, c in target:
            out[r][c] = marker
    return out
