{
 "content": "def transform(grid):
    from collections import Counter
    h=len(grid);w=max(map(len,grid));bg=Counter(v for row in grid for v in row).most_common(1)[0][0]
    # Detect a long bent line; vertical segment's color is the replacement color.
    hooks=[]
    for c in range(w):
        for color in range(10):
            if color==bg:continue
            r=0
            while r<h:
                if c>=len(grid[r]) or grid[r][c]!=color:r+=1;continue
                a=r
                while r<h and c<len(grid[r]) and grid[r][c]==color:r+=1
                b=r-1
                if b-a+1<4:continue
                for e in (a,b):
                    l=0;x=c-1
                    while x>=0 and grid[e][x]==color:l+=1;x-=1
                    rr=0;x=c+1
                    while x<len(grid[e]) and grid[e][x]==color:rr+=1;x+=1
                    if max(l,rr)>=2:hooks.append((b-a+1,color,c,e,-1 if l>rr else 1))
    out=[row[:] for row in grid]
    if not hooks:return out
    _,mark,mc,elbow,side=max(hooks)
    # Recolor a same-color object aligned on the far side of the vertical key;
    # shape target is the component with nearest matching vertical center.
    seen=set(); objects=[]
    for r in range(h):
        for c in range(len(grid[r])):
            color=grid[r][c]
            if color in (bg,mark) or (r,c) in seen:continue
            st=[(r,c)];seen.add((r,c));comp=[]
            while st:
                x,y=st.pop();comp.append((x,y))
                for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                    nx,ny=x+dx,y+dy
                    if 0<=nx<h and 0<=ny<len(grid[nx]) and grid[nx][ny]==color and (nx,ny) not in seen:
                        seen.add((nx,ny));st.append((nx,ny))
            rs=[x for x,y in comp];cs=[y for x,y in comp]
            if (side<0 and max(cs)<mc) or (side>0 and min(cs)>mc):
                objects.append((abs(sum(rs)/len(rs)-elbow),-len(comp),comp))
    if objects:
        comp=min(objects,key=lambda x:(x[0],x[1]))[2]
        for r,c in comp:out[r][c]=mark
    return out
