 "content": "def transform(grid):
    from collections import Counter

    h = len(grid)
    w = max(map(len, grid))
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]

    # Find the longest vertical stroke which turns into a horizontal arm.
    guides = []
    for c in range(w):
        for color in range(10):
            if color == background:
                continue
            r = 0
            while r < h:
                if c >= len(grid[r]) or grid[r][c] != color:
                    r += 1
                    continue
                start = r
                while r < h and c < len(grid[r]) and grid[r][c] == color:
                    r += 1
                end = r - 1
                if end - start + 1 < 3:
                    continue
                for elbow in (start, end):
                    left = 0
                    x = c - 1
                    while x >= 0 and grid[elbow][x] == color:
                        left += 1
                        x -= 1
                    right = 0
                    x = c + 1
                    while x < len(grid[elbow]) and grid[elbow][x] == color:
                        right += 1
                        x += 1
                    if max(left, right) >= 2:
                        guides.append((end - start + 1, color, c, elbow, left, right))

    out = [row[:] for row in grid]
    if not guides:
        return out
    _, marker, axis, elbow, left_arm, right_arm = max(guides)
    # The arm points away from the target. Find the closest connected object
    # on the other side, measured first by distance from the elbow row.
    target_side = 1 if left_arm > right_arm else -1
    seen = set()
    candidates = []
    for r in range(h):
        for c in range(len(grid[r])):
            color = grid[r][c]
            if color in (background, marker) or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            component = []
            while stack:
                x, y = stack.pop()
                component.append((x, y))
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nx, ny = x + dx, y + dy
                    if (0 <= nx < h and 0 <= ny < len(grid[nx])
                            and grid[nx][ny] == color and (nx, ny) not in seen):
                        seen.add((nx, ny))
                        stack.append((nx, ny))
            rows = [x for x, _ in component]
            cols = [y for _, y in component]
            if target_side > 0 and min(cols) <= axis:
                continue
            if target_side < 0 and max(cols) >= axis:
                continue
            row_gap = max(min(rows) - elbow, elbow - max(rows), 0)
            col_gap = (min(cols) - axis if target_side > 0
                       else axis - 1 - max(cols))
            candidates.append((row_gap, col_gap, -len(component), component))

    if candidates:
        component = min(candidates, key=lambda item: item[:3])[3]
        for r, c in component:
            out[r][c] = marker
    return out
"
}

