{
 "content": "def transform(grid):
    from collections import Counter

    h = len(grid)
    w = max(map(len, grid))
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]

    # Find the longest vertical stroke with a horizontal endpoint arm.
    guides = []
    for c in range(w):
        r = 0
        while r < h:
            if c >= len(grid[r]) or grid[r][c] == background:
                r += 1
                continue
            color = grid[r][c]
            start = r
            while r < h and c < len(grid[r]) and grid[r][c] == color:
                r += 1
            end = r - 1
            if end - start + 1 < 3:
                continue
            for elbow in (start, end):
                left = 0
                x = c - 1
                while x >= 0 and grid[elbow][x] == color:
                    left += 1
                    x -= 1
                right = 0
                x = c + 1
                while x < len(grid[elbow]) and grid[elbow][x] == color:
                    right += 1
                    x += 1
                if max(left, right) >= 2:
                    guides.append((end - start + 1, color, c, elbow, left, right))
    if not guides:
        return out

    _, marker, axis, elbow, left, right = max(guides)
    # The target is on the side opposite the arm.
    target_left = right >= left
    seen = set()
    choices = []
    for r in range(h):
        for c in range(len(grid[r])):
            color = grid[r][c]
            if color in (background, marker) or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            comp = []
            while stack:
                x, y = stack.pop()
                comp.append((x, y))
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nx, ny = x + dx, y + dy
                    if (0 <= nx < h and 0 <= ny < len(grid[nx])
                            and grid[nx][ny] == color and (nx, ny) not in seen):
                        seen.add((nx, ny))
                        stack.append((nx, ny))
            if target_left and max(c for _, c in comp) >= axis:
                continue
            if not target_left and min(c for _, c in comp) <= axis:
                continue
            distance = min(abs(r - elbow) + abs(c - axis) for r, c in comp)
            choices.append((distance, -len(comp), comp))

    if choices:
        target = min(choices, key=lambda item: (item[0], item[1]))[2]
        for r, c in target:
            out[r][c] = marker
    return out
